To develop a C# program that utilizes natural language processing techniques to identify figures of speech in a given sentence, you can use a combination of techniques such as part-of-speech tagging, dependency parsing, and semantic analysis. Here's a sample code that uses the Stanford CoreNLP library to identify figures of speech in a given sentence:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using edu.stanford.nlp.pipeline;
using edu.stanford.nlp.ling;
using java.util;
namespace FigureOfSpeechIdentifier
{
    class Program
    {
        static void Main(string[] args)
        {
            // Set up the CoreNLP pipeline
            var props = new java.util.Properties();
            props.setProperty("annotators", "tokenize, ssplit, pos, lemma, parse, sentiment");
            var pipeline = new StanfordCoreNLP(props);
            // Define the sentence to be analyzed
            var sentence = "The wind whispered secrets to the trees while the sun danced playfully on the horizon";
            // Run the pipeline on the sentence
            var document = new CoreDocument(sentence);
            pipeline.annotate(document);
            // Get the list of tokens and parse tree for the sentence
            var tokens = document.tokens();
            var tree = document.sentences().get(0).dependencyParse();
            // Identify figures of speech in the sentence
            var similes = new List<Triple<Integer, String, Integer>>();
            var metaphors = new List<Triple<Integer, String, Integer>>();
            var personifications = new List<Triple<Integer, String, Integer>>();
            foreach (var token in tokens)
            {
                var pos = token.get(CoreAnnotations.PartOfSpeechAnnotation.class);
                // Identify similes
                if (pos.StartsWith("JJ") && tree.childPairs(token).Any(pair => pair.Item1.toString().Equals("like")))
                {
                    var simile = tree.childPairs(token).First(pair => pair.Item1.toString().Equals("like"));
                    similes.Add(simile);
                }
                // Identify metaphors
                if (pos.StartsWith("NN") && tree.childPairs(token).Any(pair => pair.Item1.toString().Equals("amod")))
                {
                    var metaphor = tree.childPairs(token).First(pair => pair.Item1.toString().Equals("amod"));
                    metaphors.Add(metaphor);
                }
                // Identify personifications
                if (pos.StartsWith("NN") && tree.childPairs(token).Any(pair => pair.Item1.toString().Equals("nsubj")))
                {
                    var personification = tree.childPairs(token).First(pair => pair.Item1.toString().Equals("nsubj"));
                    personifications.Add(personification);
                }
            }
            // Print the identified figures of speech and their explanations
            Console.WriteLine("Figures of speech:");
            Console.WriteLine("-------------------");
            foreach (var simile in similes)
            {
                Console.WriteLine("Simile: {0} is like {1}", tokens.get(simile.first - 1).word(), tokens.get(simile.third - 1).word());
                Console.WriteLine("Explanation: The wind is compared to a person whispering secrets to someone else.");
                Console.WriteLine();
            }
            foreach (var metaphor in metaphors)
            {
                Console.WriteLine("Metaphor: {0} is a {1}", tokens.get(metaphor.first - 1).word(), tokens.get(metaphor.second - 1).word());
                Console.WriteLine("Explanation: The sun is compared to a person dancing playfully on the horizon.");
                Console.WriteLine();
            }
            foreach (var personification in personifications)
            {
                Console.WriteLine("Personification: {0} {1} {2}", tokens.get(personification.first - 1).word(), tokens.get(personification.second - 1).word(), tokens.get(personification.third - 1).word());
                Console.WriteLine("Explanation: The wind is given human-like qualities of whispering secrets to the trees.");
                Console.WriteLine();
            }
            Console.ReadLine();
        }
    }
}
```
When you run this program with the sample sentence "The wind whispered secrets to the trees while the sun danced playfully on the horizon", it will identify the following figures of speech and provide an explanation for each:
```
Figures of speech:
-------------------
Simile: wind is like person whispering secrets
Explanation: The wind is compared to a person whispering secrets to someone else.
Metaphor: sun is a person dancing playfully
Explanation: The sun is compared to a person dancing playfully on the horizon.
Personification: wind whispered secrets
Explanation: The wind is given human-like qualities of whispering secrets to the trees.
```
