func calculateImpact(culturalFactor: CulturalFactor, gdp: Double) -> (Double, Double) {
    let needs = culturalFactor.impactOnNeeds * gdp
    let wants = culturalFactor.impactOnWants * gdp
    if let nextFactor = culturalFactor.next {
        let (nextNeeds, nextWants) = calculateImpact(culturalFactor: nextFactor, gdp: gdp)
        return (needs + nextNeeds, wants + nextWants)
    } else {
        return (needs, wants)
    }
}
