To arrange the numbers 1 to 9 into three rows of three numbers each such that the sum of the numbers in each row is the same, we can follow the below steps:
1. First, we need to find the sum of all the numbers from 1 to 9, which is 45.
2. Since we need to arrange the numbers in three rows of three numbers each, the sum of each row should be 45/3 = 15.
3. We can start by iterating through the array of numbers from 1 to 9 and finding pairs of numbers whose sum is equal to 15. Once we find a pair, we can mark those two numbers as used by setting their values to -1.
4. Next, we can iterate through the array again and find a triplet of numbers whose sum is equal to 15. We can skip the numbers that have been marked as used in step 3.
5. Finally, we can output the three rows of three numbers each and the sum of each row.
Here's the C++ code that implements the above algorithm:
```
#include<iostream>
using namespace std;
int main(){
    int a[]={1,2,3,4,5,6,7,8,9};
    int sum=0;
    for(int i=0;i<9;i++)
        sum+=a[i];
    int row_sum=sum/3;

    // Find pairs of numbers whose sum is equal to row_sum
    for(int i=0;i<9;i++){
        for(int j=i+1;j<9;j++){
            int temp=a[i]+a[j];
            if(temp==row_sum){
                cout<<a[i]<<" "<<a[j]<<endl;
                a[i]=a[j]=-1;
                break;
            }
        }
    }

    // Find a triplet of numbers whose sum is equal to row_sum
    for(int i=0;i<9;i++){
        if(a[i]==-1) continue;
        for(int j=i+1;j<9;j++){
            if(a[j]==-1) continue;
            int temp=a[i]+a[j];
            if(temp==row_sum){
                for(int k=j+1;k<9;k++){
                    if(a[k]==-1) continue;
                    temp+=a[k];
                    if(temp==row_sum){
                        cout<<a[i]<<" "<<a[j]<<" "<<a[k]<<endl;
                        a[i]=a[j]=a[k]=-1;
                        break;
                    }
                    temp-=a[k];
                }
                break;
            }
        }
    }

    cout<<"The sum of each row is "<<row_sum<<endl;
    return 0;
}
```
