Here's a Python function that recommends a list of laptops based on the customer's budget and desired specifications:
```
def recommend_laptops(budget, brand=None, processor=None, memory=None, storage=None):
    laptops = [
        {"brand": "Dell", "model": "Inspiron 15 3000", "price": 499, "processor": "Intel Core i3", "memory": 4, "storage": 256},
        {"brand": "HP", "model": "Pavilion x360", "price": 599, "processor": "Intel Core i5", "memory": 8, "storage": 512},
        {"brand": "Lenovo", "model": "IdeaPad 3", "price": 449, "processor": "AMD Ryzen 5", "memory": 8, "storage": 256},
        {"brand": "Acer", "model": "Aspire 5", "price": 549, "processor": "Intel Core i5", "memory": 8, "storage": 512},
        {"brand": "ASUS", "model": "VivoBook 15", "price": 399, "processor": "AMD Ryzen 3", "memory": 4, "storage": 128}
    ]

    recommended_laptops = []
    for laptop in laptops:
        if laptop["price"] <= budget:
            if brand is not None and laptop["brand"].lower() != brand.lower():
                continue
            if processor is not None and laptop["processor"].lower() != processor.lower():
                continue
            if memory is not None and laptop["memory"] != memory:
                continue
            if storage is not None and laptop["storage"] != storage:
                continue
            recommended_laptops.append(laptop)

    return recommended_laptops
```
