//Setup function
function setup(xml) {
  var characters = xml.getElementsByTagName("characters")[0];
  var characterList = characters.getElementsByTagName("character");
  var setting = xml.getElementsByTagName("setting")[0];

  var charactersDiv = document.createElement("div");
